package com.skatesuv.eskate

import android.os.Bundle
import android.os.Handler
import android.os.Looper
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

object RiderAssistantControlBridge {
    @Volatile
    var handler: ((String) -> Pair<Boolean, String>)? = null

    fun execute(action: String): Bundle {
        val current = handler
            ?: return result(false, "SKATESUV no está preparada para recibir órdenes")

        if (Looper.myLooper() == Looper.getMainLooper()) {
            return runCatching {
                val (ok, message) = current(action)
                result(ok, message)
            }.getOrElse { result(false, "No se pudo ejecutar la orden") }
        }

        val latch = CountDownLatch(1)
        var response = result(false, "No se pudo ejecutar la orden")
        Handler(Looper.getMainLooper()).post {
            response = runCatching {
                val (ok, message) = current(action)
                result(ok, message)
            }.getOrElse { result(false, "No se pudo ejecutar la orden") }
            latch.countDown()
        }
        if (!latch.await(2, TimeUnit.SECONDS)) return result(false, "SKATESUV no respondió a tiempo")
        return response
    }

    private fun result(ok: Boolean, message: String) = Bundle().apply {
        putBoolean("ok", ok)
        putString("message", message)
    }
}

package com.skatesuv.eskate

import android.content.ContentProvider
import android.content.ContentValues
import android.database.Cursor
import android.database.MatrixCursor
import android.net.Uri
import android.os.Binder
import android.os.Process

class RiderAssistantProvider : ContentProvider() {
    companion object {
        const val AUTHORITY = "com.skatesuv.eskate.riderbridge"
        private val SNAPSHOT_URI = Uri.parse("content://$AUTHORITY/snapshot")
    }

    override fun onCreate(): Boolean = true

    override fun query(
        uri: Uri,
        projection: Array<out String>?,
        selection: String?,
        selectionArgs: Array<out String>?,
        sortOrder: String?
    ): Cursor {
        enforceSameApp()
        val cursor = MatrixCursor(arrayOf("json"))
        if (uri == SNAPSHOT_URI) {
            val snapshot = context
                ?.getSharedPreferences("rider_assistant_bridge", android.content.Context.MODE_PRIVATE)
                ?.getString("snapshot", null)
            if (!snapshot.isNullOrBlank()) cursor.addRow(arrayOf(snapshot))
        }
        return cursor
    }

    override fun call(method: String, arg: String?, extras: android.os.Bundle?): android.os.Bundle {
        enforceSameApp()
        if (method != "control") return android.os.Bundle().apply {
            putBoolean("ok", false)
            putString("message", "Orden no compatible")
        }
        val action = arg.orEmpty().trim()
        if (action.isEmpty()) return android.os.Bundle().apply {
            putBoolean("ok", false)
            putString("message", "Orden vacía")
        }
        return RiderAssistantControlBridge.execute(action)
    }

    private fun enforceSameApp() {
        if (Binder.getCallingUid() != Process.myUid()) {
            throw SecurityException("Acceso no autorizado")
        }
    }

    override fun getType(uri: Uri): String? = if (uri == SNAPSHOT_URI) "application/json" else null
    override fun insert(uri: Uri, values: ContentValues?): Uri? = throw UnsupportedOperationException("Solo lectura")
    override fun delete(uri: Uri, selection: String?, selectionArgs: Array<out String>?): Int = throw UnsupportedOperationException("Solo lectura")
    override fun update(uri: Uri, values: ContentValues?, selection: String?, selectionArgs: Array<out String>?): Int = throw UnsupportedOperationException("Solo lectura")
}

