package com.skatesuv.eskate

import java.net.HttpURLConnection
import java.net.URLEncoder
import java.net.URL
import java.nio.charset.StandardCharsets
import java.util.Locale
import org.json.JSONObject
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.roundToInt

enum class RouteHighlightKind { PEAK, PLACE, VIEWPOINT, LAKE, PASS, REFUGE, MONUMENT }

data class RouteHighlight(
    val name: String,
    val kind: RouteHighlightKind,
    val latitude: Double,
    val longitude: Double,
    val profileIndex: Int,
    val elevationMeters: Double? = null
)

fun adaptiveElevationPeaks(elevations: List<Double>): List<Int> {
    if (elevations.size < 3) return elevations.indices.toList()
    val spread = (elevations.maxOrNull() ?: 0.0) - (elevations.minOrNull() ?: 0.0)
    val prominenceThreshold = max(12.0, spread * 0.08)
    val window = max(2, elevations.size / 18)
    val spacing = max(3, elevations.size / 14)
    val candidates = (1 until elevations.lastIndex).mapNotNull { index ->
        val value = elevations[index]
        if (value < elevations[index - 1] || value < elevations[index + 1]) return@mapNotNull null
        val leftMin = elevations.subList(max(0, index - window), index + 1).minOrNull() ?: value
        val rightMin = elevations.subList(index, minOf(elevations.size, index + window + 1)).minOrNull() ?: value
        val prominence = value - max(leftMin, rightMin)
        if (prominence >= prominenceThreshold) index to prominence else null
    }.sortedByDescending { it.second }
    val selected = mutableListOf<Int>()
    candidates.forEach { (index, _) -> if (selected.none { abs(it - index) < spacing }) selected += index }
    val globalMaximum = elevations.indices.maxByOrNull { elevations[it] } ?: 0
    if (selected.none { abs(it - globalMaximum) < spacing }) selected += globalMaximum
    return selected.sorted()
}

fun fetchRouteHighlights(profile: List<Pair<Double, Double>>, elevations: List<Double>): List<RouteHighlight> {
    if (profile.size < 2) return emptyList()
    val found = mutableListOf<RouteHighlight>()

    // A failed/slow Overpass chunk must never cancel POIs from the rest of the route.
    routeHighlightChunks(profile).forEach { chunk ->
        fetchHighlightChunk(chunk, profile, elevations)?.let(found::addAll)
    }

    // Real route-derived altitude landmarks are a fallback only. They guarantee that the profile
    // has useful markers even if all public POI services are temporarily unavailable.
    if (elevations.size == profile.size && elevations.isNotEmpty()) {
        // Always keep several REAL route-derived landmarks available. Named OSM places remain
        // preferred, but a quiet/remote route must never render an empty item lane.
        val fallbackIndices = linkedSetOf<Int>()
        fallbackIndices += adaptiveElevationPeaks(elevations)
        if (profile.size >= 5) {
            fallbackIndices += profile.lastIndex / 4
            fallbackIndices += profile.lastIndex / 2
            fallbackIndices += profile.lastIndex * 3 / 4
        }
        fallbackIndices += elevations.indices.maxByOrNull { elevations[it] } ?: 0
        fallbackIndices.sorted().forEach { index ->
            val point = profile.getOrNull(index) ?: return@forEach
            val elevation = elevations[index]
            found += RouteHighlight(
                name = "Cota ${elevation.roundToInt()} m",
                kind = RouteHighlightKind.PEAK,
                latitude = point.first,
                longitude = point.second,
                profileIndex = index,
                elevationMeters = elevation
            )
        }
    }

    val deduplicated = found.sortedBy { it.profileIndex }.distinctBy {
        val latKey = (it.latitude * 10_000.0).toInt()
        val lonKey = (it.longitude * 10_000.0).toInt()
        "${it.name.lowercase(Locale.ROOT)}|$latKey|$lonKey"
    }
    return selectInformativeHighlights(deduplicated, profile.size)
}

private fun routeHighlightChunks(profile: List<Pair<Double, Double>>): List<List<Pair<Double, Double>>> {
    if (profile.size <= 3) return listOf(profile)
    val chunks = mutableListOf<List<Pair<Double, Double>>>()
    var start = 0
    while (start < profile.lastIndex) {
        var end = start + 1
        var spanMeters = 0.0
        while (end < profile.size) {
            val segment = approximateMeters(profile[end - 1].first, profile[end - 1].second, profile[end].first, profile[end].second)
            if (end > start + 1 && spanMeters + segment > 24_000.0) break
            spanMeters += segment
            end++
            if (end - start >= 12) break
        }
        val endExclusive = end.coerceAtMost(profile.size)
        chunks += profile.subList(start, endExclusive)
        if (endExclusive >= profile.size) break
        start = (endExclusive - 2).coerceAtLeast(start + 1)
    }
    return chunks
}

private data class RouteProjection(val profileIndex: Int, val distanceMeters: Double)

private fun projectToProfile(latitude: Double, longitude: Double, profile: List<Pair<Double, Double>>): RouteProjection? {
    if (profile.isEmpty()) return null
    if (profile.size == 1) return RouteProjection(0, approximateMeters(latitude, longitude, profile[0].first, profile[0].second))
    val metersPerLonDegree = 111_320.0 * kotlin.math.cos(Math.toRadians(latitude)).coerceAtLeast(0.05)
    fun localXY(point: Pair<Double, Double>): Pair<Double, Double> = (point.second - longitude) * metersPerLonDegree to (point.first - latitude) * 111_320.0
    var bestDistance = Double.MAX_VALUE
    var bestProfilePosition = 0.0
    for (index in 0 until profile.lastIndex) {
        val (ax, ay) = localXY(profile[index])
        val (bx, by) = localXY(profile[index + 1])
        val dx = bx - ax
        val dy = by - ay
        val lengthSquared = dx * dx + dy * dy
        val t = if (lengthSquared <= 0.0001) 0.0 else (-(ax * dx + ay * dy) / lengthSquared).coerceIn(0.0, 1.0)
        val px = ax + dx * t
        val py = ay + dy * t
        val distance = kotlin.math.sqrt(px * px + py * py)
        if (distance < bestDistance) { bestDistance = distance; bestProfilePosition = index + t }
    }
    return RouteProjection(bestProfilePosition.roundToInt().coerceIn(profile.indices), bestDistance)
}

private fun fetchHighlightChunk(chunk: List<Pair<Double, Double>>, fullProfile: List<Pair<Double, Double>>, elevations: List<Double>): List<RouteHighlight>? = runCatching {
    // Keep the search corridor useful for nearby landmarks without flooding the route with distant POIs.
    val padding = 0.020
    val south = chunk.minOf { it.first } - padding
    val north = chunk.maxOf { it.first } + padding
    val west = chunk.minOf { it.second } - padding
    val east = chunk.maxOf { it.second } + padding
    val bbox = String.format(Locale.US, "%.6f,%.6f,%.6f,%.6f", south, west, north, east)
    val query = """
        [out:json][timeout:18];
        (
          nwr["name"]["natural"="peak"]($bbox);
          nwr["name"]["place"~"city|town|village|hamlet|locality"]($bbox);
          nwr["name"]["tourism"="viewpoint"]($bbox);
          nwr["name"]["natural"="water"]["water"~"lake|reservoir"]($bbox);
          nwr["name"]["water"~"lake|reservoir"]($bbox);
          nwr["name"]["mountain_pass"="yes"]($bbox);
          nwr["name"]["tourism"~"alpine_hut|wilderness_hut|picnic_site|attraction"]($bbox);
          nwr["name"]["amenity"="shelter"]($bbox);
          nwr["name"]["highway"="rest_area"]($bbox);
          nwr["name"]["bridge"]($bbox);
          nwr["name"]["historic"]($bbox);
        );
        out center tags;
    """.trimIndent()
    val encoded = URLEncoder.encode(query, StandardCharsets.UTF_8.toString())
    val root = JSONObject(routeHighlightHttpGet(encoded))
    val elements = root.optJSONArray("elements") ?: return@runCatching emptyList()
    val result = mutableListOf<RouteHighlight>()
    for (i in 0 until elements.length()) {
        val element = elements.optJSONObject(i) ?: continue
        val tags = element.optJSONObject("tags") ?: continue
        val name = tags.optString("name:es").ifBlank { tags.optString("name") }.trim()
        if (name.isBlank()) continue
        val center = element.optJSONObject("center")
        val lat = if (element.has("lat")) element.optDouble("lat") else center?.optDouble("lat") ?: continue
        val lon = if (element.has("lon")) element.optDouble("lon") else center?.optDouble("lon") ?: continue
        val projection = projectToProfile(lat, lon, fullProfile) ?: continue
        val nearest = projection.profileIndex
        val kind = when {
            tags.optString("natural") == "peak" -> RouteHighlightKind.PEAK
            tags.optString("tourism") == "viewpoint" -> RouteHighlightKind.VIEWPOINT
            tags.optString("natural") == "water" || tags.optString("water") in setOf("lake", "reservoir") -> RouteHighlightKind.LAKE
            tags.optString("mountain_pass") == "yes" -> RouteHighlightKind.PASS
            tags.optString("tourism") in setOf("alpine_hut", "wilderness_hut") || tags.optString("amenity") == "shelter" -> RouteHighlightKind.REFUGE
            tags.has("historic") -> RouteHighlightKind.MONUMENT
            else -> RouteHighlightKind.PLACE
        }
        val allowedDistance = when (kind) {
            RouteHighlightKind.PEAK, RouteHighlightKind.VIEWPOINT -> 2_000.0
            RouteHighlightKind.LAKE, RouteHighlightKind.PASS, RouteHighlightKind.REFUGE -> 1_500.0
            RouteHighlightKind.PLACE -> 1_600.0
            RouteHighlightKind.MONUMENT -> 1_000.0
        }
        if (projection.distanceMeters > allowedDistance) continue
        val osmElevation = tags.optString("ele").replace(',', '.').filter { it.isDigit() || it == '.' || it == '-' }.toDoubleOrNull()
        result += RouteHighlight(name, kind, lat, lon, nearest, osmElevation ?: elevations.getOrNull(nearest))
    }
    result
}.getOrNull()

private fun selectInformativeHighlights(found: List<RouteHighlight>, profileSize: Int): List<RouteHighlight> {
    if (found.size < 2) return found
    // Do not let fallback Cotas displace real named geographic POIs.
    val realNamed = found.filterNot { it.name.startsWith("Cota ") }
    val fallback = found.filter { it.name.startsWith("Cota ") }
    val spacing = max(2, profileSize / 18)
    val selected = mutableListOf<RouteHighlight>()
    realNamed.sortedByDescending { highlightPriority(it.kind) }.forEach { candidate ->
        if (selected.none { abs(it.profileIndex - candidate.profileIndex) < spacing }) selected += candidate
    }
    fallback.forEach { candidate ->
        if (selected.size < 8 && selected.none { abs(it.profileIndex - candidate.profileIndex) < spacing }) selected += candidate
    }
    return selected.sortedBy { it.profileIndex }.take(10)
}

private fun highlightPriority(kind: RouteHighlightKind): Int = when (kind) {
    RouteHighlightKind.PEAK -> 7
    RouteHighlightKind.PASS -> 6
    RouteHighlightKind.VIEWPOINT -> 5
    RouteHighlightKind.PLACE -> 4
    RouteHighlightKind.LAKE -> 3
    RouteHighlightKind.REFUGE -> 2
    RouteHighlightKind.MONUMENT -> 1
}

private fun approximateMeters(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
    val dy = (lat1 - lat2) * 111_320.0
    val dx = (lon1 - lon2) * 111_320.0 * kotlin.math.cos(Math.toRadians((lat1 + lat2) / 2.0))
    return kotlin.math.sqrt(dx * dx + dy * dy)
}

private fun routeHighlightHttpGet(encodedQuery: String): String {
    val endpoints = listOf(
        "https://overpass-api.de/api/interpreter?data=",
        "https://overpass.kumi.systems/api/interpreter?data=",
        "https://overpass.nchc.org.tw/api/interpreter?data="
    )
    var lastError: Exception? = null
    endpoints.forEach { endpoint ->
        val connection = URL(endpoint + encodedQuery).openConnection() as HttpURLConnection
        try {
            connection.connectTimeout = 9_000
            connection.readTimeout = 18_000
            connection.requestMethod = "GET"
            connection.setRequestProperty("User-Agent", "E-SKATE-Skatesuv/0.7")
            connection.setRequestProperty("Accept-Language", "es")
            if (connection.responseCode in 200..299) return connection.inputStream.bufferedReader().use { it.readText() }
        } catch (error: Exception) { lastError = error } finally { connection.disconnect() }
    }
    throw lastError ?: IllegalStateException("Overpass no disponible")
}

