package com.skatesuv.eskate;

import android.content.Intent;
import com.eskatesuv.ridervoz.RiderVoiceActivity;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;

@CapacitorPlugin(name = "SkateIntegration")
public class SkateIntegrationPlugin extends Plugin {
    @PluginMethod
    public void openMainScreen(PluginCall call) {
        String screen = call.getString("screen", "HOME");
        AppNavigationBridge.request(screen);
        if (getActivity() != null) {
            getActivity().finish();
            JSObject result = new JSObject();
            result.put("ok", true);
            result.put("screen", screen);
            call.resolve(result);
        } else {
            call.reject("No hay actividad disponible");
        }
    }

    @PluginMethod
    public void closeModule(PluginCall call) {
        if (getActivity() != null) {
            getActivity().finish();
            JSObject result = new JSObject();
            result.put("ok", true);
            call.resolve(result);
        } else {
            call.reject("No hay actividad que cerrar");
        }
    }

    @PluginMethod
    public void openRiderVoice(PluginCall call) {
        String rider = call.getString("rider", "");
        String riderName = call.getString("name", "");
        String group = call.getString("group", "");
        Intent intent = new Intent(getContext(), RiderVoiceActivity.class);
        if (rider != null && !rider.isEmpty()) intent.putExtra("rider", rider);
        if (riderName != null && !riderName.isEmpty()) intent.putExtra("riderName", riderName);
        if (group != null && !group.isEmpty()) intent.putExtra("group", group);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        getContext().startActivity(intent);
        JSObject result = new JSObject();
        result.put("ok", true);
        call.resolve(result);
    }
}

