package com.skatesuv.eskate

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

object AppNavigationBridge {
    var requestedScreen: Screen? by mutableStateOf(null)
        private set

    @JvmStatic
    fun request(screen: String) {
        requestedScreen = when (screen.uppercase()) {
            "HOME", "INICIO" -> Screen.HOME
            "DATA", "DATOS", "PERFORMANCE" -> Screen.PERFORMANCE
            "MAP", "MAPA", "NAV", "NAVEGACION", "NAVEGACIÓN" -> Screen.MAP
            "SETTINGS", "AJUSTES" -> Screen.SETTINGS
            "COMMUNITY", "COMUNIDAD" -> Screen.COMMUNITY
            else -> Screen.HOME
        }
    }

    @JvmStatic
    fun clear() {
        requestedScreen = null
    }
}
